-- N1: seed/update full HTML body for contratto quadro standard (tipo 1)
-- Source: contratto_quadro_standard_template.html (firme allineate al PDF storico)

UPDATE contratti_template
SET
  html_body = '<p style="margin:0 0 8pt 0;text-align:center;font-weight:bold;line-height:1.2;font-size:12pt;font-family:Arial,Helvetica,sans-serif;">CONTRATTO DI TRASPORTO DI MERCI SU STRADA N. {{contratto_numero}}/{{anno}}</p>
<p style="margin:0 0 4pt 0;text-align:center;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Tra</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Committente</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Autotrasporti Pigliacelli S.p.A. con sede a Veroli (FR) in via Sant’Anna n. 80, Partita Iva, Codice Fiscale e n. di iscrizione al Registro delle Imprese di Frosinone 00169560604, R.E.A. 59333, in persona del Consigliere Delegato sig. Marcello Pigliacelli, nato ad Alatri (FR) il 03/01/1963 (di seguito Committente), che opera secondo il sistema di qualità conforme ai requisiti della normativa internazionale ISO 9001/2015 e</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">{{vettore_ragione_sociale}} con sede a {{vettore_citta}} ({{vettore_provincia}}), Via {{vettore_indirizzo}} n. {{vettore_civico}}, Codice Fiscale, P. Iva e numero di iscrizione al Registro Imprese di {{vettore_reg_imprese_luogo}} {{vettore_reg_imprese_n}}, R.E.A. {{vettore_rea}}, iscritta all’Albo Nazionale degli Autotrasportatori di cose per conto terzi al n. {{vettore_albo}}, iscritta al REN (Registro Elettronico Nazionale delle imprese che sono autorizzate all’esercizio della professione di trasportatore di merci o persone su strada), in persona del suo Legale rappresentante sig. {{rapp_nome}} {{rapp_cognome}}, nato a {{rapp_luogo_nascita}} ({{rapp_prov_nascita}}) il {{rapp_data_nascita}} (di seguito Vettore)</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">si conviene e stipula quando segue:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 1) IDENTIFICAZIONI DELLE PARTI E OGGETTO DEL CONTRATTO:</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Proprietario Merci</strong>: vedi (Allegato A)</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Caricatore Delle Merci</strong>: vedi (Allegato A)</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Oggetto del presente Contratto sono i servizi di trasporto che il Vettore eseguirà su ordine del Committente in conformità a quanto pattuito nel presente Contratto. Il presente atto costituisce l’unico contratto esistente tra le parti: pertanto eventuali accordi o intese pregresse sono da considerarsi superati.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">In particolare, l''oggetto del contratto consiste nell''esecuzione, da parte del Vettore, dei servizi di trasporto di merci come da Allegato A (Tipologia Merce, Tariffe e Tempi di Carico e Scarico), che saranno ordinati dal Committente, nell’esecuzione dei contratti da questi conclusi con i suoi mittenti, con i tempi e le modalità di seguito indicate e a fronte del corrispettivo previsto nel successivo articolo 10 del presente Contratto.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Oggetto del presente Contratto sono i servizi di trasporto in quanto tali, anche nel caso in cui siano eseguiti con più autoveicoli del Vettore ed abbiano continuità nel tempo. Le obbligazioni contratte dal Vettore non costituiscono un contratto di appalto di servizi, non essendo il Vettore impegnato ad una specifica organizzazione di uomini e di mezzi, né costituiscono un impegno “a fermo” per l’esecuzione del complesso dei servizi stessi. In particolare, il Vettore si impegna ad eseguire ogni singolo servizio, consistente nel trasporto delle merci dal luogo di carico a quello di scarico e riconsegna.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Il presente contratto è stipulato ai sensi dell’art. 2 del Decreto Dirigenziale del Ministero delle Infrastrutture e dei Trasporti in data 1° febbraio 2006, pubblicato sulla G. U. n. 31 del 7 febbraio 2006, in forza del quale le parti mantengono “la facoltà di scegliere altre formulazioni contrattuali” diverse da quelle di cui al predetto decreto “purché contengano gli elementi essenziali di cui all’art. 6, comma 3” del D. Lgs. n. 286 del 2005.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Il Contratto disciplina tutti i trasporti che il Committente di volta in volta commissionerà al Vettore (nel seguito del presente atto indicati anche semplicemente come le “Consegne”), che dovranno essere eseguiti dal Vettore utilizzando automezzi che abbiano portata utile e caratteristiche tecniche idonee e compatibili con la tipologia ed il quantitativo di merce da trasportare.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Le Parti si danno vicendevolmente atto che il Committente non assume alcun obbligo di esclusiva nei confronti del Vettore, cosicché sarà totalmente libero di affidare l’esecuzione di trasporti e, in particolare, di trasporti analoghi a quelli di cui al presente contratto, anche ad altri autotrasportatori, così come non assume alcun impegno in termini di volumi di traffico. Le Parti si danno altresì vicendevolmente atto che nessun impegno in termini di esclusiva viene assunto dal Vettore. Gli allegati formano parte integrante e sostanziale del Contratto, come pure l''Ordine di Carico, il Documento di Trasporto e/o i documenti equipollenti emessi in relazione a ciascuna Consegna, in cui sono indicati in dettaglio eventuali elementi integrativi del contratto.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Preliminarmente alla stipulazione del presente contratto la Autotrasporti Pigliacelli S.p.a. ha eseguito sul portale dell''Albo dell''autotrasporto la verifica sulla regolarità del vettore ai sensi dell''art. 1, comma 248 della legge 23 dicembre 2014 n. 190, e, all''esito delle risultanze delle elaborazioni tecniche effettuate sulla base dei dati trasmessi in via telematica dalle Amministrazioni ed Enti competenti, la posizione del vettore è risultata regolare con riferimento all''iscrizione all''Albo nazionale degli autotrasportatori, all''iscrizione al Registro Elettronico Nazionale, alla Camera di Commercio ed alla regolarità contributiva.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 2) ELEMENTI ESSENZIALI DEL CONTRATTO</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Le Parti si danno vicendevolmente atto che le Consegne:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- avranno ad oggetto merci della tipologia indicata nell’Allegato A e/o specificata mediante annotazione nell''Ordine di Carico e/o nel Documento di Trasporto e/o nei documenti equipollenti emessi in relazione a ciascuna Consegna;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- avranno ad oggetto il quantitativo di tali merci specificato mediante annotazione nell''Ordine di Carico e/o nel Documento di Trasporto e/o nei documenti equipollenti emessi in relazione a ciascuna Consegna, fermo restando che il Vettore dovrà mettere a disposizione per il trasporto un veicolo idoneo ad eseguirlo, anche con riferimento al rispetto delle indicazioni contenute nella relativa carta di circolazione;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- avranno i luoghi di presa in consegna della merce da parte del Vettore e di riconsegna della stessa al destinatario specificati di volta in volta mediante annotazione nell''Ordine di Carico e/o nel Documento di Trasporto e/o nei documenti equipollenti emessi in relazione a ciascuna Consegna;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- saranno remunerati con i corrispettivi e secondo le modalità indicate nel successivo articolo 10;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- verranno eseguiti utilizzando i mezzi individuati nell’ Allegato B (Elenco mezzi), fermo restando che:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">a. il Vettore avrà facoltà di utilizzare mezzi diversi da quelli ivi indicati dandone comunicazione al Committente in forma scritta (anche a mezzo fax o a mezzo e-mail) prima della presa in consegna della merce, indicando tutti gli estremi identificativi del veicolo utilizzato, compresa la portata utile;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">b. il Vettore assume specifico impegno di aggiornare la lista dei mezzi di cui all’Allegato B, secondo le modalità indicate nel successivo articolo 19;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- avranno quale caricatore il Committente, ovvero il diverso soggetto indicato mediante annotazione nell''Ordine di Carico e/o nel Documento di Trasporto e/o nei documenti equipollenti emessi in relazione a ciascuna Consegna;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- avranno i tempi massimi per il carico e lo scarico della merce indicati nell’Allegato A.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Tenuto conto del fatto che il presente contratto regola una pluralità di trasporti in relazione ai quali non possono essere previamente individuati tutti gli elementi essenziali di cui all’art. 6, comma III, del D.Lgs. 286/05, gli elementi essenziali mancanti e specifici di ogni singolo trasporto verranno indicati mediante annotazione nell''Ordine di Carico e/o nel Documento di Trasporto e/o nei documenti equipollenti - che le Parti considerano parti integranti e sostanziali del presente contratto in forma scritta ai sensi del D.Lgs. 286/05 – emessi in occasione di ogni trasporto o gruppo di trasporti commissionati dal Committente al Vettore. Le Parti si danno vicendevolmente atto che le indicazioni eventualmente contenute nell’Ordine di Carico e/o nel Documento di Trasporto e/o nei documenti equipollenti in relazione a ciascuna Consegna prevalgono su quanto pattuito nel Contratto, ove incompatibili, in quanto le Parti concordemente attribuiscono ad essi efficacia derogativa.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 3) OBBLIGHI DEL VETTORE</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> assume specifico impegno ed obbligo di:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- di attenersi scrupolosamente alle politiche, alle procedure, alle istruzioni operative, alle norme comportamentali e di sicurezza, contenute nel Manuale del Vettore;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- eseguire le Consegne con la migliore diligenza possibile, utilizzando veicoli, strumenti, attrezzature e risorse umane idonee all’esecuzione delle Consegne stesse ed in misura adeguata per la corretta e puntuale esecuzione;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- eseguire le Consegne attenendosi scrupolosamente alle indicazioni impartite ed a quanto previsto dal Contratto e dai suoi allegati;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- prendere in consegna la merce all’interno del Deposito nelle zone predisposte per il carico sugli automezzi;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- segnalare al personale addetto al Deposito e al Committente eventuali vizi della merce e/o degli imballi da trasportare e farne annotazione sui relativi documenti di trasporto, fermo restando che in caso di mancata formulazione di specifiche riserve la merce e gli imballi si considereranno essere stati presi in carico dal Vettore in perfetto stato;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- controllare, a carico ultimato, la correttezza e la sicurezza dello stesso;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- ritirare i documenti di trasporto che dovranno essere sottoscritti dal Vettore e far sottoscrivere gli stessi agli addetti del destinatario per ricevuta;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- provvedere a mettere i prodotti trasportati a disposizione del destinatario, nel luogo, nel termine e con le modalità previste dalla presente scrittura o comunque indicate dal Committente nell''Ordine di Carico e/o nel Documento di Trasporto e/o nei documenti equipollenti emessi in relazione a ciascuna Consegna;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- segnalare al Committente, al termine di ciascuna Consegna, le circostanze che abbiano ostacolato la regolarità del servizio;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- inoltrare al Committente e a tutte le Parti interessate copia dei documenti di trasporto e doganali, inclusa la ricevuta di intercambio di attrezzature;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- produrre al Committente, a sua semplice richiesta, la documentazione certificativa dell’iscrizione all’Albo degli autotrasportatori di cose per conto di terzi (o altro titolo abilitativo), il certificato di iscrizione alla CCIAA, il certificato REN, la documentazione certificativa dell’iscrizione all’Albo Gestori Ambientali, le autorizzazioni e la documentazione tecnica relativa alle attrezzature in dotazione agli automezzi (quali in via esemplificativa e non esaustiva, cronotachigrafi ecc.), nonché le carte di circolazione degli automezzi stessi ed ogni altro documento relativo alla regolarità amministrativa dell’attività vettoriale svolta e/o all’idoneità degli automezzi e/o all’idoneità del personale di cui il Vettore si avvale;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- fornire al Committente, al momento della conclusione del contratto, nonché durante la vigenza dello stesso con cadenza trimestrale e/o su specifica richiesta del Committente, la documentazione attestante la regolarità del versamento dei contributi assicurativi e previdenziali, rilasciata dagli enti previdenziali in data non anteriore a tre mesi.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> nella pianificazione del viaggio dovrà tener conto della presenza durante il percorso di aree in cui poter sostare l’automezzo garantendo la sicurezza del proprio personale e del mezzo individuando parcheggio sicuri e aree di sosta autorizzate.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> raccoglie i dati sulle emissioni di gas ad effetto serra provenienti dai propri mezzi.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">I veicoli utilizzati per le Consegne dovranno in ogni caso:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- essere in regola con le vigenti disposizioni in tema di circolazione stradale, di autotrasporto ed in generale di trasporto di cose, di trasporto di rifiuti pericolosi e non pericolosi, di merci e rifiuti in regime ADR, di merci alimentari e zootecniche;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- avere portata utile idonea al quantitativo di merce da trasportare, nel rispetto delle disposizioni del Codice della Strada e della normativa vigente;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- essere oggetto di regolare manutenzione, ordinaria e straordinaria, meccanica e di carrozzeria;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- essere attrezzati con ogni strumento e/o dotazione necessari per affrontare i trasporti in sicurezza nel rispetto delle norme a tutela della circolazione stradale;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- in caso di trasporto con silo veicoli, essere revisionati secondo quanto disposto dalla normativa vigente e controllati con cadenza programmata sul corpo del silo veicolo, sui tubi flessibili, sugli elementi di sicurezza, sulle culatte e passi d’uomo e su ogni altro elemento della cisterna;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- essere lavati esclusivamente in stazioni di lavaggio indicate dal Committente;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- avere a bordo del veicolo la documentazione idonea a dimostrare il titolo in base al quale l’autista presta servizio presso il Vettore stesso e, se il conducente è cittadino extracomunitario, l''attestato del conducente di cui al regolamento (CE) n. 484/2002 del Parlamento europeo e del Consiglio del 1° marzo 2002 e s.m.i..</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- implementare il programma BBS per la guida e per il carico/scarico, secondo le linee guida Cefic BBS su detti temi.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> si impegna inoltre a garantire che, nei trasporti di merci confezionate (in sacchi, cartoni, balle ecc.) effettuati con automezzi “cassonati” e/o furgonati, i piani di carico, le sponde e le pareti siano perfettamente puliti ed in ottimo stato d’uso, ed in particolare che non presentino fessure e/o sporgenze come chiodi, schegge ecc. che possano in qualsiasi modo danneggiare le merci trasportate.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Nell’esecuzione delle Consegne, il Vettore sarà tenuto (ed assume specifica obbligazione in tal senso) a rispettare e far rispettare rigorosamente dai suoi dipendenti, preposti, collaboratori e/o ausiliari:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- tutte le disposizioni legislative, regolamentari e di altro genere, ivi compresi gli ordini impartiti dalle Autorità a ciò preposte, poste a tutela della sicurezza della circolazione stradale, con particolare riferimento</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">a. quelle in materia di autotrasporto di merci per conto di terzi;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">b. quelle in materia di sagoma limite (art. 61); massa limite (art. 62); limiti di velocità (art. 142); sistemazione del carico sui veicoli (art. 164); trasporto di cose su veicoli a motore e sui rimorchi (art. 167); durata della guida degli autoveicoli (art. 174) di cui al D. Lgs. 30 aprile 1992, n. 285 e successive modificazioni e integrazioni;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">c. tutte le disposizioni legislative, regolamentari e di altro genere, ivi compresi gli ordini impartiti dalle Autorità a ciò preposte, in materia di sicurezza sociale e, in particolare, quelle:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">i) relative all’osservanza dei contratti collettivi ed individuali di lavoro;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">ii) relative alla previdenza ed assistenza;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">iii) relative alla sicurezza sul lavoro.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">d) tutte le disposizioni vigenti in materia di tempi di guida e riposo, nonché in materia di rispetto dei tempi di archiviazione dei dischi cronotachigrafici.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> dichiara inoltre di essere a conoscenza e si obbliga a rispettare le disposizioni vigenti in materia di trasporto rifiuti di cui al D.Lgs. 152/06 e s.m.i. Il trasporto di detti prodotti dovrà, altresì, avvenire nel pieno rispetto delle indicazioni contenute nella carta di circolazione dei veicoli adibiti al trasporto degli stessi. Con la sottoscrizione del presente accordo il Vettore dichiara la regolarità della propria iscrizione all’Albo nazionale degli autotrasportatori (o di altro titolo abilitativo), nonché dell’esercizio dell’attività di autotrasporto e degli eventuali servizi accessori. Il Vettore, pertanto, risponde integralmente della violazione di tali disposizioni e si impegna a tenere il Committente manlevato ed indenne da qualsiasi pregiudizio che il Committente stesso dovesse subire in conseguenza di ogni pretesa, richiesta o azione, da chiunque, a qualsiasi titolo ed in qualsiasi sede, avanzata in relazione e in conseguenza della violazione delle disposizioni legislative e regolamentari poste a tutela della sicurezza della circolazione stradale e della sicurezza sociale. Resteranno, quindi, a carico del Vettore tutti i relativi danni, costi, oneri e spese, nonché le sanzioni civili, penali e amministrative, e quant’altro, previste dalla normativa vigente in materia.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 4) SUB-VETTORI</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> non può a sua volta affidare ad altro vettore, neanche parzialmente, lo svolgimento della prestazione di trasporto.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> si impegna a manlevare e a tenere indenne il Committente da eventuali sanzioni comminate al Committente per la violazione dell’obbligo suindicato.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Il mancato rispetto dei sopradetti impegni costituisce inadempimento contrattuale e consentirà al Committente di considerare risolto di diritto il presente contratto ai sensi dell’art. 1456 c.c. con comunicazione trasmessa al Vettore a mezzo fax ovvero e-mail o con qualunque altra modalità idonea allo scopo.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 5) DOCUMENTI EMESSI IN RELAZIONE AD OGNI CONSEGNA.</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Committente</strong>, nei casi previsti dalle disposizioni vigenti, emetterà e consegnerà al Vettore per ogni servizio, salvo per i trasporti di merci a collettame, l''Ordine di Carico e/o il Documento di Trasporto e/o i documenti equipollenti, con indicazione degli elementi previsti dal D.Lgs. 286/05 e dalle successive norme di attuazione.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> consegnerà al Committente (contestualmente e/o antecedentemente alla presa in consegna della merce) copia dell''Ordine di Carico e/o del Documento di Trasporto e/o dei documenti equipollenti da esso (e/o da suo personale a tal fine delegato, in forza di espresso e formale mandato in tal senso) sottoscritti.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> si impegna espressamente a conservare copia dei documenti indicati dal comma 1 dell’articolo 7-bis del D.l. 286/05, sul mezzo con cui è eseguita la Consegna, come previsto dalle disposizioni normative vigenti.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Contestualmente alla presa in consegna della merce l’autista consegnerà al Committente copia dell’Ordine di Trasporto sottoscritta dal Vettore ovvero sottoscriverà l’Ordine laddove agisca in nome e per conto del Vettore, in forza di espresso e formale mandato in tal senso.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 6) ESECUZIONE DELLE CONSEGNE</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Le Parti si danno vicendevolmente atto che il rispetto delle vigenti disposizioni legislative e regolamentari poste a tutela della sicurezza della circolazione stradale e della sicurezza sui luoghi di lavoro costituisce un valore primario, che deve necessariamente prevalere su ogni loro pattuizione. In questa prospettiva, il Committente si impegna ad impartire al Vettore istruzioni compatibili con il rispetto di tale normativa, sia per quanto attiene ai quantitativi di merce caricati su ogni singolo mezzo sia per quanto attiene alla tempistica di consegna, mentre il Vettore si impegna a segnalare immediatamente al Committente il caso in cui gli venissero impartite istruzioni anche solo potenzialmente incompatibili con il rispetto di tale normativa ed a non rispettare eventuali istruzioni che dovessero essere impartite dal personale della Committente e/o da terzi incompatibili con tale normativa.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Fermo restando quanto sopra previsto, le Parti si danno altresì vicendevolmente atto che la particolare natura dell’attività prestata dal Vettore impone il rispetto dei tempi di consegna concordati e specificati.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Le istruzioni impartite dal Committente al Vettore relative alla tempistica di consegna dovranno essere contenute nell’Ordine di Carico e/o nel Documento di Trasporto (e/o nei documenti equipollenti emessi in relazione a ciascuna Consegna) consegnati al Vettore prima dell’inizio del viaggio, ovvero in altro documento scritto, cosicché eventuali indicazioni orali impartite dal personale addetto al carico e/o da dipendenti del Committente e/o da terzi dovranno considerarsi prive di effetti, come se non fossero mai state impartite. Il Vettore si impegna a garantire il rispetto delle suddette istruzioni, fatta salva in ogni caso la necessità di evitare la violazione delle norme poste a tutela della sicurezza della circolazione stradale.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong>, nel caso in cui fosse in ritardo rispetto ai tempi previsti per la presa in carico e/o per la consegna, dovrà darne immediata comunicazione al Committente telefonicamente, indicando anche le ragioni del ritardo, in modo tale da consentirle di predisporre, ove possibile, quanto necessario per minimizzare gli effetti negativi del ritardo, ferma restando ogni responsabilità del Vettore in tale caso. Il Vettore in caso di guasti meccanici agli automezzi dovrà in particolare mettere a disposizione del Committente un veicolo sostitutivo, comunque idoneo all’esecuzione del trasporto interessato, indicandone per iscritto gli estremi identificativi, fermo restando che il Committente si riserva facoltà di valutare a suo insindacabile giudizio se affidare la prosecuzione del servizio ad altro vettore.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong>, in caso di emergenze che si manifestano durante l’esecuzione del servizio di trasporto affidatogli, potrà contattare i seguenti numeri:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">· Logistica Silos Tel. +39 0775 812306</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">· Logistica Cassonati, Vasche e Walking Floor Tel. +39 0775 812301</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">· Logistica Centinati Tel. +39 0775 812314</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">· 24/24 Tel. +39 0775 308105</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 7) OBBLIGHI DEL COMMITTENTE</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Committente</strong> si impegna:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- a pagare i corrispettivi di cui all’articolo 10 a fronte dei servizi eseguiti dal Vettore;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 8) RESPONSABILITÀ DEL VETTORE</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">8.1 Il Vettore si assume ogni e qualsiasi responsabilità connessa all’esecuzione delle Consegne affidategli, rispondendo integralmente per rotture e/o manomissioni delle merci trasportate ai sensi dell’art. 1693 c.c., dal momento del carico delle stesse sino alla consegna agli addetti del destinatario.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">In caso di perdita e/o avaria della merce trasportata, il Vettore sarà ritenuto responsabile secondo quanto previsto dall’art. 1696 cod. civ..</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> non potrà in ogni caso opporre alcuna limitazione della responsabilità nel caso in cui la perdita o l''avaria della merce siano stati determinati da dolo o colpa grave del Vettore stesso o dei suoi dipendenti e preposti, ovvero di ogni altro soggetto di cui egli si sia avvalso per l''esecuzione del trasporto. In particolare, ma non in via esaustiva, le Parti danno atto che saranno sempre considerate ipotesi di colpa grave le seguenti fattispecie: impiego di sub-vettori non autorizzati ai sensi dell’art. 4 del presente contratto; lasciare incustoditi gli automezzi, le merci affidate e/o i documenti di trasporto e di accompagnamento merci; il mancato rispetto delle norme e disposizioni del Codice della Strada.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> si impegna a stipulare e mantenere in vigore per l’intera durata del presente Contratto, a sua cura e spese, con primaria compagnia di assicurazioni una o più polizze, di massimale/i adeguato/i, a copertura degli eventuali danni sopra indicati con estensione alla garanzia C (furto o mancata riconsegna merci), nonché a</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">copertura della responsabilità civile verso terzi, ed a provvedere al regolare versamento dei relativi premi, fornendo, a semplice richiesta del Committente, copia del contratto e/o della Polizza quietanzata. Il Vettore si impegna a comunicare al Committente eventuali cause di nullità e/o limitazione delle coperture stesse.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Committente</strong> avrà in ogni caso facoltà di compensare integralmente gli importi ad esso spettati a titolo di risarcimento dei danni subiti per perdita e/o avaria delle cose trasportate con quelli dovuti al Vettore a titolo di corrispettivi per le Consegne.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Nel caso di inadempimento dell’obbligo di stipulare la polizza assicurativa, il Vettore sarà soggetto a rivalsa da parte della compagnia assicurativa del Committente e/o sarà tenuto all’integrale risarcimento dei danni nei confronti di quest’ultima in relazione al valore della merce, al danneggiamento dei beni di proprietà della stessa e/o per eventuali franchigie assicurative.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">8.2 Il Vettore manleva espressamente il Committente da ogni e qualsiasi danno diretto ed indiretto possa derivare a terzi, persone e/o cose, al personale, ai beni mobili ed immobili del Committente, del Caricatore, del Destinatario e/o di terzi, per effetto, anche solo indiretto e mediato, dell’esecuzione dei trasporti oggetto del presente contratto, per fatto del personale del Vettore o di ulteriori soggetti di cui si sia avvalso, direttamente o indirettamente, nell’esecuzione delle prestazioni contrattuali. Il Vettore provvederà a stipulare una idonea polizza di assicurazione a copertura della responsabilità civile verso terzi con primaria compagnia assicurativa a copertura di tutti i rischi suddetti con adeguati massimali, inviandone copia al Committente. Il Vettore non può esercitare, nei confronti del Proprietario delle merci e/o Cliente, azione diretta per conseguire il pagamento di quanto dovuto.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">8.3 Il Vettore si impegna a rispettare e a far rispettare al proprio personale, nella esecuzione dei servizi di trasporto affidatigli dal Committente, le norme in materie ambientale tra cui, a titolo esemplificativo ma non esaustivo, il D.Lgs. 152/2006 s.m.i., la normativa ADR, il Codice della Strada e ogni altra normativa vigente afferente alle attività svolte, non espressamente indicata nel presente contratto. Il Vettore è da ritenersi esclusivo responsabile dei danni procurati a sé e/o a terzi che conseguono direttamente e/o indirettamente dalle violazioni delle norme suindicate. Il Vettore si impegna a manlevare il Committente da qualsiasi responsabilità, civile, penale, economica, che possa derivare da tali violazioni.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 9) RITARDO</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Le Consegne avverranno nel rispetto dei termini indicati nel contratto e/o nell''Ordine di Carico e/o nei documenti equipollenti emessi in relazione a ciascuna Consegna. Il Vettore si impegna a garantire il rispetto dei suddetti termini, fatta salva in ogni caso la necessità di evitare la violazione delle norme poste a tutela della sicurezza della circolazione stradale.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong>, nel caso in cui fosse in ritardo rispetto ai tempi previsti per la presa in carico e/o per la consegna, dovrà darne immediata comunicazione al Committente telefonicamente, indicando anche le ragioni del ritardo, in modo tale da consentirgli di predisporre, ove possibile, quanto necessario per minimizzare gli effetti negativi del ritardo.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 10) CORRISPETTIVO DEL TRASPORTO E FATTURAZIONE</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">10.1 Le tariffe di trasporto di cui all’ Allegato A sono il corrispettivo per il servizio effettuato dal luogo di carico fino al luogo di scarico, nonché di ogni altra prestazione dovuta dal Vettore ai sensi del presente contratto.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">I corrispettivi pattuiti comprendono qualsiasi onere necessario per l’esecuzione del trasporto (pedaggi, carnet, T.I.R., diritti di transito, equipaggiamento del veicolo, dotazioni particolari per la protezione del personale viaggiante, ecc.), compresi i tempi di attesa al carico ed allo scarico, e tengono conto dei principi di adeguatezza in materia di sicurezza stradale e sociale.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Tutti i corrispettivi sono da considerarsi al netto di IVA e potranno essere soggetti a revisione solamente in caso di variazione delle modalità operative dei servizi di trasporto, previo accordo scritto fra le Parti.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Il vettore dichiara che i corrispettivi sono stati concordati in piena autonomia, e non costituiscono abuso di dipendenza economica.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">10.2 Le Parti convengono che i corrispettivi dei servizi di trasporto rimarranno in ogni caso, per tutta la durata del presente Contratto, quelli dell’Allegato A, e sono stati determinati e concordati tra le parti tenendo conto dei principi di adeguatezza in materia di sicurezza stradale e sociale, nonché dei costi di esercizio dell''impresa del vettore, ed i costi per i servizi di programmazione dei viaggi, e sono ritenuti congrui con riferimento ai costi di esercizio che il vettore sostiene per l’esecuzione dei servizi oggetto del presente contratto, anche secondo quanto previsto dal decreto direttoriale del Ministero delle Infrastrutture e della Mobilità Sostenibile con riguardo alle tabelle relative ai valori di riferimento dei costi di esercizio delle imprese di autotrasporto ai sensi della Legge n.190/2014. Il corrispettivo come sopra determinato è da considerarsi a tutti gli effetti comprensivo ed omnicomprensivo di qualsiasi onere accessorio per l’esecuzione del trasporto, inclusi anche gli oneri relativi all’eventuale gestione degli imballaggi/pallets ai sensi di quanto previsto dall’articolo 11 bis D.Lgs. 286/05. Per quanto attiene ai tempi massimi di carico e scarico della merce le Parti stabiliscono in due ore il periodo massimo di franchigia, sia per il carico sia per lo scarico, oltre il quale il vettore avrà diritto al pagamento di un’indennità calcolata secondo quanto disposto dall’articolo 6 bis D.Lgs. 286/05.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">10.3 Ai sensi dell’art. 6 del D.Lgs. 21.11.2005, n. 286, come modificato dall’art. 14 del D.L. 22 marzo 2022, n. 21, le Parti dichiarano che il valore del gasolio preso a riferimento al momento della stipulazione del contratto è €2.100,00/1.000 litri Iva inclusa. Il corrispettivo potrà essere modificato solo ed esclusivamente di comune accordo tra le parti e, in caso di necessità, potrà essere adeguato, in aumento o in diminuzione, in osservanza di quanto previsto dall’art. 6, 3° comma, del D.Lgs. 21.11.2005, n. 286, come modificato dal D.L. 21.03.2022, n. 21. Gli adeguamenti che venissero a determinarsi, se in aumento, saranno corrisposti dal Committente al Vettore previa fattura integrativa di quest’ultimo entro il mese di competenza, se in diminuzione saranno addebitati dal Committente al Vettore mediante emissione di fattura e trattenuti dal Committente mediante compensazione con le somme dovute, entro il termine di giorni 60 dall’emissione della fattura.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">10.4 Nel caso di trasporti il cui corrispettivo non può essere determinato ai sensi dell’Allegato A, i corrispettivi dovuti al Vettore saranno concordati di volta in volta al momento dell’ordine e saranno indicati nell''Ordine di Carico e/o nel Documento di Trasporto e/o nei documenti equipollenti emessi in relazione a ciascuna Consegna, ma le condizioni generali previste dal presente contratto si intendono estese anche a tali trasporti.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">10.5 In deroga alla previsione del comma 12 dell’art. 83 bis della legge 133/08, il pagamento del corrispettivo avverrà a giorni 60+28 dalla data di emissione di ogni singola fattura a mezzo B.B..</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Nel caso in cui il Committente intenda contestare la regolarità degli importi fatturati dovrà entro il termine 60 gg. dal ricevimento di ogni singola fattura specificare al Vettore le ragioni della contestazione, a pena di decadenza.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">10.6 Il Vettore decadrà definitivamente ed irrevocabilmente dalla possibilità di sollevare qualsiasi tipo di contestazione in ordine alle tariffe applicate e tenute in considerazione agli effetti della fatturazione ed in ordine ai presupposti di fatto della fatturazione, trascorso il termine di 180 gg. dalla data di emissione di ogni singola fattura.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Agli effetti di cui ai commi precedenti, le Parti convengono che:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- al fine di evitare di incorrere nelle predette decadenze, la Parte che intende sollevare una contestazione dovrà inviare all’altra, entro il termine sopra specificato, una lettera raccomandata A.R.;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- tale missiva dovrà contenere – sempre a pena di decadenza - analitica e specifica indicazione delle contestazioni e dei rilievi sollevati nonché il conteggio delle differenze e/o degli errori riscontrati, con specificazione delle conseguenti variazioni;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- i termini di pagamento concordati decorreranno, in caso di contestazione, dalla data di esecuzione delle variazioni.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 11) CONSEGNE AGGIUNTIVE</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">11.1 La disciplina del presente Contratto troverà applicazione anche per le Consegne non indicate nell’Allegato A ed eventualmente concordate tra le Parti successivamente alla sottoscrizione del Contratto stesso.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">11.2 Il corrispettivo per le Consegne suindicate sarà determinato secondo quanto disposto dall’art. 10 del presente Contratto.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 12) DURATA E RECESSO</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Il Contratto decorre dalla data di sua sottoscrizione e ha durata sino al 31 dicembre dello stesso anno.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Alla predetta scadenza il rapporto si intende tacitamente rinnovato per l’anno solare successivo (e così via anche successivamente) qualora non venga data disdetta con almeno tre mesi di preavviso a mezzo di lettera raccomandata a.r..</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Le Parti hanno facoltà di recedere anticipatamente dal rapporto a mezzo fax o e-mail, che dovrà essere inviata dalla Parte che intende esercitare tale diritto all’altra, entro il 30 novembre dell’anno solare al termine del quale intende ottenere la risoluzione del rapporto. La facoltà di recedere dev’essere obbligatoriamente confermata a mezzo lettera raccomandata a.r.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 13) DISPOSIZIONI RELATIVE AL PERSONALE DEL VETTORE</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> garantisce espressamente che, per lo svolgimento del servizio oggetto del presente contratto, si avvarrà esclusivamente di personale qualificato, di sicura moralità, al quale verrà assicurato un trattamento economico e normativo conforme alle vigenti disposizioni di legge e/o di contratto collettivo in materia di diritto del lavoro e della previdenza sociale (a titolo esemplificativo, le norme in materia retributiva, contributiva previdenziale, assicurativa, igienico – sanitaria ed infortunistica).</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> si impegna ad implementare e a garantire il rispetto, da parte di tutto il proprio personale, di una Politica volta a contrastare l’utilizzo di droghe e alcol.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> assume ogni responsabilità relativa al personale addetto al servizio, manlevando e tenendo indenne il Committente da qualsiasi responsabilità per infortunio e/o danno a cose e/o a persone di qualsiasi genere che dovesse derivare dall’espletamento dei Servizi e/o per qualsiasi richiesta anche di risarcimento danni da parte di terzi.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> garantisce il pieno rispetto delle vigenti disposizioni in materia di lavoro; in ogni caso, le relative responsabilità derivanti da inosservanza delle relative normative, sia civili che penali, rimarranno sempre a totale carico del Vettore.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">A tal proposito il Vettore dichiara di utilizzare risorse, mezzi e personale adeguatamente organizzati al fine di garantire la tutela della salute e della sicurezza dei lavoratori impiegati a svolgere l’opera richiesta.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> si impegna a rispettare tutti gli obblighi derivanti da leggi e norme in tema di sicurezza ed igiene sul lavoro, con particolare riferimento al T.U. sulla sicurezza del lavoro D.L. 81/2008 e successive modificazioni, fornendo al proprio personale le dotazioni ed i dispositivi antinfortunistici idonei ed appropriati al tipo di attività oggetto del presente contratto e verificando, per il tramite dei propri responsabili preposti, la sistematica e corretta applicazione delle norme impartite nonché l’utilizzo delle dotazioni fornite. Il Vettore si impegna a formare/informare ed addestrare il proprio personale conformemente a quanto previsto dal D.Lgs. 81/08 e s.m.i, a formare il proprio personale sull’utilizzo dei D.P.I.. Il Vettore si impegna a gestire, a registrare, nonché a monitorare, le non conformità, gli incidenti, gli infortuni e i quasi incidenti (c.d. near miss). Il Vettore si impegna a rispettare e a far rispettare al proprio personale la normativa nazionale ed internazionale vigente in materia di tempi di guida e riposo, nonché in materia di rispetto dei tempi di archiviazione dei dischi cronotachigrafici.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> si impegna altresì a manlevare il Committente da qualsiasi pretesa e/o istanza del proprio personale, assumendo la responsabilità e tutti gli oneri relativi ed esonerando espressamente il Committente da qualsiasi pretesa e/o richiesta economica che possa essere avanzata nei confronti di quest’ultimo per qualsiasi titolo, ragione o causale (anche a titolo di risarcimento del danno) comunque dipendente o relativa al personale (e così a titolo esemplificativo e non esaustivo, retribuzioni, differenze retributive, accantonamenti del TFR, versamenti contributivi e previdenziali, infortuni sul lavoro).</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> si impegna a esigere dai propri dipendenti un contegno corretto durante il servizio ed in particolare far rispettare le prescrizioni in materia di sicurezza della circolazione stradale dettate dal vigente Codice della Strada o da altre disposizioni di legge, dando allo stesso adeguate e precise istruzioni al riguardo.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Committente</strong> garantisce la gestione e la registrazione delle non conformità rilevate e si riserva di comunicare al Vettore i nominativi degli autisti che:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- abbiano avuto diverbi litigiosi e/o discussioni con dipendenti del Committente e/o con terzi in occasione del servizio;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- non abbiano osservato disposizioni date dal Committente al Vettore riguardanti le modalità di esecuzione delle Consegne;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">A fronte della comunicazione di cui al comma precedente, il Vettore si impegna a non utilizzare ulteriormente per l’esecuzione delle Consegne l’autista utilizzato nel servizio in cui si è verificato uno dei fatti di cui sopra e sia stato segnalato dal Committente.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 14) DIVIETO DI CESSIONE DEL CONTRATTO</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Il presente contratto deve intendersi stipulato “intuitus personae” e non può essere ceduto, in tutto o in parte, senza il previo consenso scritto della parte ceduta.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 15) TRACCIABILITA’ DEI FLUSSI FINANZIARI</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Ai sensi e per gli effetti dell’art. 3, comma 8, della Legge 13 agosto 2010 n. 136, il Vettore si impegna a rispettare gli obblighi di tracciabilità dei flussi finanziari previsti dalla medesima Legge 136/2010. In ottemperanza a quanto disposto dall’art. 3, comma 9 bis della Legge 136/2010 il contratto si risolverà di diritto, ai sensi degli artt. 1456 e 1360 cod. civ., nell’ipotesi in cui per le transazioni eseguite non siano utilizzati il bonifico bancario o postale ovvero gli altri strumenti idonei a consentire la piena tracciabilità delle operazioni, ai sensi e per gli effetti della Legge n. 136/2010. Il Vettore si obbliga, a mente dell’art. 3, comma 9 della Legge n. 136/2010, ad inserire negli eventuali contratti sottoscritti con i subappaltatori o i subcontraenti coinvolti, direttamente o indirettamente, nella prestazione delle attività e/o servizi oggetto del contratto, a pena di nullità assoluta, un’apposita clausola con la quale ciascuno di essi assume gli obblighi di tracciabilità dei flussi finanziari di cui alla medesima Legge n. 136/2010. Di tale inserimento il Vettore renderà apposita dichiarazione ai sensi e per gli effetti del DPR 445/2000. Resta inteso tra le parti che Autotrasporti Pigliacelli Spa si riserva il diritto di effettuare un’indagine a campione circa la veridicità delle dichiarazioni, a tal uopo, rese dal Vettore, di talché in esito delle stesse, riscontrata una dichiarazione non veritiera il contratto si intenderà risolto di diritto. Il Vettore si impegna a comunicare al Committente il conto corrente dedicato alle transazioni commerciali sottoposte alla disciplina della Legge n. 136/2010.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 16 RISERVATEZZA E TUTELA DATI PERSONALI</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Le Parti convengono che tutti i dati e le informazioni necessarie all’esecuzione del presente contratto possono essere trattate solo per dare esecuzione allo stesso e sono protette da un reciproco obbligo di confidenzialità e riservatezza.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Le Parti si impegnano a conformarsi ad ogni obbligo previsto dal Regolamento (UE) 2016/679 del Parlamento Europeo e del Consiglio del 27 aprile 2016 concernente la “tutela delle persone fisiche con riguardo al trattamento dei dati personali e la libera circolazione dei di tali dati” (di seguito “GDPR”), nonché alle normative nazionali in materia ed ai provvedimenti dell’Autorità Garante per la protezione dei dati personali. Con l’accettazione del contratto, il Vettore riconosce e dà atto che i dati personali (e.g. nominativi, indirizzo email aziendale, ecc.) di propri dipendenti/collaboratori, coinvolti nelle attività di cui al presente contratto, saranno comunicati a Autotrasporti Pigliacelli Spa e da quest’ultima trattati in qualità di Titolare, in persona del Legale Rappresentante pro-tempore, per l’esecuzione del contratto stesso ai sensi e per gli effetti di cui agli artt. 13 e 14 del GDPR, garantendo i diritti dell’Interessato. Inoltre, il Vettore riconosce e dà atto che i predetti dati personali potranno essere comunicati da Autotrasporti Pigliacelli Spa a terzi solo se per accordo o per previsione di legge questi debbano intervenire nell’esecuzione del contratto.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 17) DISPOSIZIONI GENERALI</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Nell’ipotesi che una o più previsioni del presente contratto dovessero essere dichiarate nulle o invalide per qualsiasi ragione, le altre previsioni resteranno pienamente in vigore e le Parti si impegnano sin d’ora, nel migliore spirito di buona fede, ad adempiere alle disposizioni restate in vigore nonché a concordare e ad eseguire modalità che sostituiscano in forma valida, per il raggiungimento delle finalità del presente contratto, la o le previsioni dichiarate nulle o invalide.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">L’eventuale tolleranza di una delle Parti di comportamenti dell’altra costituenti violazioni delle disposizioni di questo contratto, non costituirà rinuncia ai diritti che derivano dalle disposizioni violate, né al diritto di esigere il corretto adempimento di tutti i termini e le condizioni contenute in questo contratto.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Articolo 18) CLAUSOLA DI DECADENZA SEMESTRALE</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Il vettore è tenuto a chiedere alla Autotrasporti Pigliacelli s.p.a., a pena di decadenza, le differenze di tariffe e/o di prezzi che egli ritenga dovute, derivanti dall’applicazione del presente contratto o dall’applicazione di qualsivoglia norma di legge vigente e futura, compreso tutto quanto previsto dall’articolo 83 bis del D.L. 112/08, convertito in Legge 133/08 e successive modifiche, anche in materia di adeguamento del corrispettivo agli incrementi del costo del gasolio e delle tariffe autostradali italiane, nonchè dalle pubblicazioni mensili del Ministero delle Infrastrutture e dei Trasporti dei valori indicativi di riferimento dei costi di esercizio di cui all’art. 1 comma 250 Legge 190/2014 e/o dai valori di riferimento delle imprese di autotrasporto, anche ai sensi dell’art. 14 del D.L. 21.03.2022, n. 21, oppure in applicazione degli usi delle Camere di Commercio e/o degli Accordi Volontari che dovessero entrare in vigore o essere conclusi sulla base del D.Lgs. 286/05 e che potessero in qualche modo trovare applicazione nel rapporto intercorrente tra le parti, posto che le stesse hanno inteso disciplinare il medesimo con espressa esclusione di ogni richiamo e di ogni riferimento a tali usi ed Accordi, nel termine perentorio di sei mesi dalla data delle fatture dei trasporti eseguiti, per i quali ritiene dovute le differenze.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Il vettore, per far valere i propri diritti nel predetto termine di decadenza semestrale, è tenuta ad inviare alla Autotrasporti Pigliacelli s.p.a. la richiesta scritta delle eventuali differenze che sarebbero dovute, dando analitica dimostrazione del calcolo. Tale richiesta deve essere inviata, sempre a pena di decadenza, alla Autotrasporti Pigliacelli s.p.a. tramite raccomandata con avviso di ricevimento, ovvero tramite PEC, nel predetto termine perentorio di sei mesi.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">La presente clausola di decadenza si intende approvata nel senso che essa costituisce parte autonoma del contratto e produce in ogni caso i suoi effetti indipendentemente dall’efficacia o nullità del contratto stesso, ovvero nel caso in cui il presente contratto sia ritenuto non concluso in forma scritta, ai sensi dell’art.6, comma 6°, D.Lgs. 21 novembre 2005, n. 286.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>ART.19) DIVIETO DI CONCORRENZA SLEALE, CLAUSOLA RISOLUTIVA ESPRESSA, PENALE</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">19.1. E’ fatto espresso divieto al Vettore di proporre offerte di servizi e concludere con i clienti del committente, contratti di trasporto che abbiano ad oggetto i servizi che costituiscono oggetto del presente contratto di trasporto o servizi analoghi.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">19.2. Le inosservanze di tale disposizione costituiscono atti di concorrenza sleale e danno diritto al risarcimento dei danni in favore del primo vettore (committente), con la conseguenza della risoluzione immediata del presente contratto, a norma dell’art. 1456 c.c., trattandosi di clausola risolutiva espressa, e sempre con il diritto al risarcimento dei danni per risoluzione anticipata del contratto stesso.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">19.3. Salva la risoluzione espressa del contratto a norma dell’art. 1456 c.c. e salvo sempre il diritto all’eventuale maggiore danno, in caso di violazione del divieto di concorrenza di cui al comma primo del presente articolo, il vettore è tenuto al pagamento a titolo di penale della somma di € 200.000,00 (Duecentomila/00).</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 20) MODIFICHE AL CONTRATTO</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Il Contratto sostituisce ad ogni fine ed effetto di legge eventuali altri accordi, contratti, patti ed intese intercorsi tra le Parti prima della sua entrata in vigore, essendo loro comune intenzione che abbia carattere novativo rispetto agli accordi in precedenza intercorsi, anche se non formalizzati per iscritto e derivanti da comportamenti concludenti.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Nessuna modifica al Contratto potrà essere considerata produttiva di effetti e vincolante per le Parti se non risultante da atto scritto, debitamente firmato da persona munita dei poteri necessari per impegnare il soggetto nel cui nome e nel cui interesse verranno sottoscritti gli eventuali patti modificativi e/o aggiuntivi.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Committente</strong> avrà peraltro facoltà di modificare in ogni momento l’Allegato A, dandone al Vettore. Nel caso in cui il Vettore non intendesse accettare tali modifiche, dovrà darne comunicazione al Committente a mezzo e-mail pec entro tre giorni dalla data di ricevimento della comunicazione di cui sopra e le Parti si incontreranno entro la settimana successiva per concordare le modifiche da apportate agli allegati.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Nel caso in cui, entro quindici giorni da tale ultimo termine, non fosse possibile addivenire ad un accordo, il rapporto si considererà consensualmente risolto senza necessità di alcuna ulteriore comunicazione o diffida.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Nel caso in cui Il Vettore non si avvalesse della facoltà di cui sopra, le modifiche agli allegati si intenderanno da lui accettate.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> dovrà invece aggiornare ogni qual volta sia necessario l’Allegato B, anche semplicemente inviando al Committente una comunicazione scritta con i nuovi dati da inserire negli allegati e/o con quelli da cancellare, fermo restando che tali comunicazioni saranno considerate quale parte integrante e sostanziale del contratto.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 21 CODICE AZIENDALE DI COMPORTAMENTO</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Autotrasporti Pigliacelli S.p.A. nella conduzione dei propri affari e nella gestione dei rapporti con i propri fornitori applica i principi indicati nel proprio Codice Aziendale di Comportamento, allegato al presente contratto (oppure visionabile sul sito www.pigliacelli.it). Il Vettore dichiara di aver compreso e di condividere tali principi, impegnandosi, per sé e per i suoi dipendenti e collaboratori, diretti e indiretti, al rispetto di tali principi consapevole che la loro violazione costituisce grave inadempimento contrattuale.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 22 MODELLO DI GESTIONE, ORGANIZZAZIONE E CONTROLLO L. 231/2001</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> dichiara di essere a conoscenza che Autotrasporti Pigliacelli S.p.A. ha adottato un Modello di organizzazione, gestione e controllo, ai sensi dell’art. 6 del D.Lgs. 8 giugno 2001 n. 231, consultabile a mezzo internet presso l’indirizzo www.pigliacelli.it destinato a regolamentare, tra l’altro, i rapporti con i terzi secondo principi di trasparenza e legalità. Il Vettore si impegna per sé, i suoi apicali, dipendenti e collaboratori, diretti e indiretti, nell’esecuzione del rapporto contrattuale con Autotrasporti Pigliacelli S.p.A., ad astenersi da qualsivoglia comportamento atto a configurare le ipotesi di reato indicate nel D.Lgs. 231/2001 e riportate nel predetto Modello di organizzazione, gestione e controllo, consapevole che il mancato rispetto ditale impegno costituisce inadempimento contrattuale e può dar luogo alla risoluzione per inadempimento, ai sensi e per gli effetti dell’art. 1456 c.c., del contratto da parte di Autotrasporti Pigliacelli Spa. Il Vettore manterrà indenne Autotrasporti Pigliacelli S.p.A. per condotte commesse dal proprio personale apicale o sottoposto.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 23) RECESSO – RISOLUZIONE</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> dichiara:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">1. Che la Società non si trova in stato di fallimento, di liquidazione, di amministrazione controllata o di concordato preventivo e che non è in corso un procedimento fallimentare o altra procedura concorsuale;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">2. Che la Società è in regola con l’adempimento degli obblighi assicurativi, contributivi e retributivi verso il proprio personale dipendente;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">3. Che la Società è in regola con l’adempimento degli obblighi in materia di sicurezza sul lavoro ed in materia ambientale.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> dichiara che né se stesso, né i soci, né il legale rappresentante, né tutti gli amministratori o dirigenti o procuratori dell’Impresa sono interessati da una o più delle seguenti situazioni:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- sottoposizione a procedimento per l’applicazione di misure di prevenzione, personali o patrimoniali, ai sensi della normativa antimafia (art. 6 ss. D.Lgs. 159/2011; art. 67 D.Lgs. 159/2011);</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- applicazione di misure cautelari coercitive nell’ambito di un procedimento penale o pronuncia di sentenza di condanna, ancorchè non definitiva, compresa quella prevista dall’art. 444 c.p.p., per i reati che incidono sull’affidabilità professionale, e tra questi per i delitti contro la Pubblica Amministrazione, per partecipazioni a reati associativi o per concorso negli stessi, per i delitti di usura, estorsione, ricettazione, riciclaggio, impiego di beni provenienti da delitti e per altre figure di reato che assumono rilievo nell’ambito della criminalità organizzata;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- applicazione di misure cautelari nell’ambito di un procedimento penale o pronuncia di sentenza di condanna, ancorché non definitiva, compresa quella emessa su richiesta delle parti, nei confronti dell’Impresa, ai sensi del D.Lgs. 231/2001, per reati che incidono sull’affidabilità professionale e tra questi i delitti contro la Pubblica Amministrazione, per partecipazione a reati associativi o per concorso negli stessi, per i delitti di usura, estorsione, ricettazione, riciclaggio, impiego di beni provenienti da delitti e per altre figure di reato che assumono rilievo nell’ambito della criminalità organizzata;</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">- informativa intedittiva antimafia della Prefettura.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Qualora si verificasse una delle situazioni sopra indicate durante il periodo di esecuzione del contratto, il Vettore sarà obbligato ad informare, entro e non oltre sette giorni dal verificarsi di tali situazioni, il Committente che si riserva la facoltà di recedere dal contratto con comunicazione trasmessa a mezzo fax ovvero e-mail o con qualunque altra modalità idonea allo scopo.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Il mancato rispetto dell’obbligo di informare, così come la dichiarazione di dati falsi o incompleti, costituirà inadempimento contrattuale e consentirà a Autotrasporti Pigliacelli S.p.A. di considerare risolto di diritto il presente contratto ai sensi dell’art. 1456 c.c. con comunicazione trasmessa al Vettore a mezzo fax ovvero e-mail o con qualunque altra modalità idonea allo scopo.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> dichiara, altresì, di essere in possesso di tutte le autorizzazioni di natura amministrativa, fiscale e ambientale previste dalle vigenti disposizioni normative per lo svolgimento della propria attività. Qualora durante</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">il periodo di esecuzione del contratto, le autorizzazioni suindicate venissero meno o subissero modifiche, il Vettore sarà obbligato ad informare il Committente, che si riserva la facoltà di recedere dal contratto con comunicazione trasmessa a mezzo fax ovvero e-mail o con qualunque altra modalità idonea allo scopo.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Il Contratto si considera risolto di diritto ai sensi dell’art. 1456 c.c., altresì, in caso di inadempimento da parte del Vettore degli obblighi di cui all’art. 4 del presente contratto, nonché nel caso in cui venisse meno la regolarità del Vettore sotto il profilo dell''adempimento degli obblighi retributivi, o previdenziali o assicurativi, o comunque il venir meno della regolarità del vettore, risultante dall''apposito portale di cui all''art. 83 bis del D.L. 25.06.2008 n. 112, conv. In l. 06.08.2008 n. 133, e s.m.i., nonché in caso di grave inadempimento da parte del Vettore di altre obbligazioni contrattuali. La risoluzione del Contratto sarà comunicata dal Committente al Vettore a mezzo fax ovvero e-mail o con qualunque altra modalità idonea allo scopo.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 24) COMPENSAZIONE</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Nel caso in cui il Vettore usufruisca di assistenza meccanica dell’officina Aer Services Srl (facente parte del Gruppo Pigliacelli), per il proprio parco veicolare e non provveda nei termini contrattuali al pagamento dei relativi compensi o fatture, si conviene e si pattuisce che il Committente, su richiesta per iscritto della Aer Service S.r.l. inviata per conoscenza anche al Vettore, è autorizzato a trattenere l’importo relativo alle fatture Aer Services Srl ed a compensare fino a concorrenza il proprio debito nei confronti del Vettore derivante dai servizi di trasporto da quest’ultimo forniti con il debito maturato dal Vettore nei confronti dell’officina Aer Services Srl, a cui verserà l’importo trattenuto e compensato.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 25) DICHIARAZIONI DEL VETTORE</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> ha consegnato al Committente, precedentemente alla sottoscrizione del presente Contratto, e si impegna a produrre al Committente ad ogni semplice richiesta:</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">a) Autocertificazione requisiti di Qualità, Ambiente e Sicurezza nei luoghi di lavoro (All. C);</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">b) Dichiarazione sostitutiva concernente l’idoneità degli automezzi, la formazione dei dipendenti e il rispetto delle norme in materia di sicurezza (All. D);</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">c) Richiesta dati anagrafici (All. E);</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">d) Questionario di qualificazione (All. F)</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">e) Dichiarazione sostitutiva antimafia (All. G)</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">f) Dichiarazione sostitutiva di accettazione del Manuale del Vettore (All. H);</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">g) Autocertificazione concernente il possesso e la validità di polizza assicurativa merci (ALL. I).</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Il Vettore</strong> garantisce la veridicità di quanto dichiarato e si impegna a comunicare tempestivamente ogni eventuale variazione. Nel caso risultasse che quanto dichiarato non corrisponda a verità o il Vettore non dichiari tempestivamente difformità o variazioni, il presente contratto potrà essere risolto per inadempimento ai sensi e per gli effetti dell’art. 1456 c.c.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">La mancata presentazione della documentazione suindicata costituirà inadempimento contrattuale e consentirà al Committente di considerare risolto di diritto il presente contratto ai sensi dell’art. 1456 c.c. con comunicazione trasmessa al Vettore a mezzo fax ovvero e-mail o con qualunque altra modalità idonea allo scopo.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>ART. 26) PRECEDENTI CONTRATTI E RINUNCIA</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Il presente contratto annulla e sostituisce integralmente ogni precedente accordo eventualmente intervenuto tra le parti; pertanto, diviene l’unico regolamento negoziale disciplinante il rapporto contrattuale tra le parti stesse. Le parti dichiarano con la sottoscrizione del presente contratto di non aver nulla a che pretendere l’una verso l’altra a qualsivoglia titolo, ragione e causa, anche risarcitoria – fatto salvo, ovviamente, il pagamento dei corrispettivi dovuti per i trasporti effettuati, e risultanti dalle fatture emesse e non ancora pagate, ovvero il risarcimento per danni alle merci non ancora definiti o conosciuti - che abbia origine o comunque sia connesso ai precedenti rapporti contrattuali ed alla esecuzione di pregresse prestazioni di autotrasporto, e segnatamente dichiarano di non aver nulla a pretendere a titolo di eventuali differenze di tariffa, di prezzo, di costi minimi e/o di valori di riferimento delle imprese di autotrasporto, anche ai sensi dell’art. 1, comma 250, della legge 23 dicembre 2014, n. 190 e dell’art. 14 del D.L. 21.03.2022, n. 21, nonché a titolo di adeguamenti del costo del gasolio preso a riferimento al momento della conclusione del contratto. Le parti si danno reciprocamente atto che tale rinuncia generale e novativa costituisce clausola essenziale del presente contratto.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 27) FORO COMPETENTE ESCLUSIVO</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Qualsiasi controversia relativa alla validità, efficacia, interpretazione e/o esecuzioni del presente contratto sarà devoluta alla competenza esclusiva del Foro di Frosinone.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;"><strong>Art. 28) DATA CERTA</strong></p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Le Parti si danno reciprocamente atto di essere a perfetta conoscenza delle modifiche introdotte all’art. 6 del D.lgs. 286/05 per quanto attiene alla data certa del presente contratto formato da nr. 16 (sedici) pagine e nr. 2 (due) Allegati (A-B), e quindi, assumono vicendevolmente l’impegno di provvedere ad attribuire al Contratto tale requisito. L’adempimento di cui sopra sarà effettuato dalla Parte più diligente entro e non oltre una settimana dalla data di sottoscrizione del Contratto e la Parte che lo avrà curato dovrà trasmettere immediatamente all’altra copia della relativa documentazione.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Letto, confermato e sottoscritto.</p>
<p style="margin:12pt 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Veroli, {{data_certa}}</p>
<p style="margin:0 0 0 0;text-align:left;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;white-space:pre;">            COMMITTENTE 				                                                      VETTORE</p>
<p style="margin:0 0 8pt 0;text-align:left;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;white-space:pre;">		___________________________					                                        _________________</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Ai sensi e per gli effetti degli articoli 1341 e 1342 c.c. si intendono specificamente approvate le seguenti clausole: art. 3) Obblighi del Vettore; art. 4) Sub-Vettori; Art. 8) Responsabilità del Vettore; Art. 9) Ritardo; Art. 10) Corrispettivo del trasporto e fatturazione; Art. 12) Durata e recesso; Art. 15) Tracciabilità dei flussi finanziari; Art. 16) Riservatezza e Tutela dati personali; Art. 18) Clausola di decadenza semestrale; Art. 19) Divieto di concorrenza sleale, clausola risolutiva espressa, penale; Art. 20) Modifiche al contratto; Art. 21) Codice aziendale di comportamento; Art. 22) Modello di gestione, organizzazione e controllo L. 231/2001; Art. 23) Recesso – Risoluzione; Art. 24) Compensazione; Art. 25) Dichiarazioni del Vettore; Art. 26) Precedenti contratti e rinuncia; Art. 27) Foro competente esclusivo.</p>
<p style="margin:0 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Letto, confermato e sottoscritto.</p>
<p style="margin:12pt 0 3.2pt 0;text-align:justify;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;">Veroli, {{data_certa}}</p>
<p style="margin:0 0 0 0;text-align:left;line-height:1.15;font-size:10pt;font-family:Arial,Helvetica,sans-serif;white-space:pre;">            COMMITTENTE 				                                                      VETTORE</p>',
  updated_at = NOW()
WHERE tipo_contratto = 1
  AND (
    codice IN ('STANDARD', 'quadro_standard', 'contratto_quadro_standard')
    OR is_default = 1
  );
